/* Neon base adapter for the Immersive Themes: a [data-immersive-theme] scope
 * points shadcn/ui's slots at the theme's --immersive-* properties, so
 * everything inside takes the theme. ImmersiveLayout imports this file and
 * sets the attribute on its root and on <html>. immersive-themes.css is
 * generated by theme/scripts/generate-immersive-themes.mjs, copied as-is. */
@import "./immersive-themes.css";

/* <html> carries the attribute too, so the body, the overscroll and overlays
 * portalled into the body take the canvas. On <html> the first selector ties
 * neon.css's :root[data-theme] blocks and wins by coming after it.
 * A theme's text is White or Navy only, so muted text is the theme's text
 * too, and cards and popovers sit on the canvas so it stays readable there.
 * Secondary, muted and accent fills (secondary and outline buttons, toggles,
 * the segmented control track, tags, list rows, menu items, table headers)
 * carry the theme's text, not their own foreground, so they take palette 75:
 * the first stepped block on a theme whose palette 100 is the canvas, and the
 * one step whose on-color is the theme's text in every theme. Accent equals
 * secondary, as bgAlternate equals bgSecondary in Neon. Inverse (the checked
 * segment, the pressed toggle, the tooltip) is the action pair, since a
 * theme's action is its text color and on-action is White or Navy. The
 * fgPrimary role (the active tab, the informational alert's icon, a ghost
 * input button) is the theme's text, or Ultra would draw it navy on navy.
 * The disabled mixes are redeclared because :root's mix resolves :root's
 * slots; every theme's action and canvas sit far apart in luminance, so
 * CDS's blend (getBlendedColor) comes to 93.7%, as in Neon light, and a
 * secondary fill blends at 75%, as in Neon. Borders, inputs and destructive
 * keep the app's roles. */
:root[data-immersive-theme],
[data-immersive-theme] {
  --background: var(--immersive-canvas);
  --foreground: var(--immersive-text);
  --muted-foreground: var(--immersive-text);
  --card: var(--immersive-canvas);
  --card-foreground: var(--immersive-text);
  --popover: var(--immersive-canvas);
  --popover-foreground: var(--immersive-text);
  --primary: var(--immersive-action);
  --primary-foreground: var(--immersive-on-action);
  --primary-disabled: color-mix(in srgb, var(--immersive-action) 93.7%, var(--immersive-canvas));
  --secondary: var(--immersive-palette-75);
  --secondary-foreground: var(--immersive-on-palette-75);
  --secondary-disabled: color-mix(in srgb, var(--immersive-palette-75) 75%, var(--immersive-canvas));
  --muted: var(--immersive-palette-75);
  --accent: var(--immersive-palette-75);
  --accent-foreground: var(--immersive-on-palette-75);
  --inverse: var(--immersive-action);
  --inverse-foreground: var(--immersive-on-action);
  --color-fgPrimary: var(--immersive-text);
  --ring: var(--immersive-action);
}

/* The canvas sets color-scheme, whatever the OS or AppRoot says: dark only on
 * Ultra's navy. AppRoot writes color-scheme inline on <html>, so these need
 * !important. ImmersiveLayout's THEME_SCHEMES holds the same choice. */
:root[data-immersive-theme] { color-scheme: light !important; }
:root[data-immersive-theme="ultra"] { color-scheme: dark !important; }
